package com.rulecraft.decisionops.decisionapi.domain;
import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="api_credential") public class ApiCredential {@Id private UUID id;@Column(name="tenant_id",nullable=false)private UUID tenantId;@Column(name="project_id",nullable=false)private UUID projectId;@Column(name="decision_service_id",nullable=false)private UUID serviceId;@Column(nullable=false,length=160)private String label;@Column(name="key_prefix",nullable=false,length=24)private String keyPrefix;@Column(name="key_hash",nullable=false,length=64)private String keyHash;@Enumerated(EnumType.STRING)@Column(nullable=false,length=16)private ApiCredentialStatus status;@Column(name="created_by",nullable=false)private UUID createdBy;@Column(name="created_by_name",nullable=false,length=160)private String createdByName;@Column(name="created_at",nullable=false)private Instant createdAt;@Column(name="revoked_by")private UUID revokedBy;@Column(name="revoked_at")private Instant revokedAt;@Version private long version;protected ApiCredential(){}public ApiCredential(UUID tenantId,UUID projectId,UUID serviceId,String label,String prefix,String hash,UUID actor,String actorName,Instant now){id=UUID.randomUUID();this.tenantId=tenantId;this.projectId=projectId;this.serviceId=serviceId;this.label=label;keyPrefix=prefix;keyHash=hash;status=ApiCredentialStatus.ACTIVE;createdBy=actor;createdByName=actorName;createdAt=now;}public void revoke(UUID actor,Instant now){status=ApiCredentialStatus.REVOKED;revokedBy=actor;revokedAt=now;}public UUID getId(){return id;}public UUID getTenantId(){return tenantId;}public UUID getProjectId(){return projectId;}public UUID getServiceId(){return serviceId;}public String getLabel(){return label;}public String getKeyPrefix(){return keyPrefix;}public String getKeyHash(){return keyHash;}public ApiCredentialStatus getStatus(){return status;}public String getCreatedByName(){return createdByName;}public Instant getCreatedAt(){return createdAt;}public Instant getRevokedAt(){return revokedAt;}public long getVersion(){return version;}}
